<div class="mx-auto max-w-7xl"><div class="mb-8"><p class="text-sm font-medium text-indigo-600">Operational control</p><h1 class="mt-1 text-2xl font-bold text-slate-900">Persediaan</h1><p class="mt-2 text-sm text-slate-500">Pantau saldo on-hand, available, reserved, dan status stok per produk.</p></div><div class="rounded-2xl border border-slate-200 bg-white shadow-sm"><div class="flex flex-col gap-3 border-b border-slate-100 p-4 sm:flex-row"><input wire:model.live.debounce.300ms="search" class="w-full rounded-xl border-slate-200 text-sm sm:max-w-xs" placeholder="Cari produk atau SKU..."><select wire:model.live="status" class="rounded-xl border-slate-200 text-sm sm:w-44"><option value="all">Semua status</option><option value="critical">Stok kritis</option><option value="safe">Stok aman</option></select></div><div class="overflow-x-auto"><table class="min-w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wider text-slate-400"><tr><th class="px-5 py-3">Produk</th><th class="px-5 py-3">On-hand</th><th class="px-5 py-3">Reserved</th><th class="px-5 py-3">Available</th><th class="px-5 py-3">Incoming</th><th class="px-5 py-3">Status</th></tr></thead><tbody class="divide-y divide-slate-100">@forelse($products as $product)@php($inventory = $product->inventory)<tr><td class="px-5 py-4"><p class="font-semibold text-slate-800">{{ $product->name }}</p><p class="text-xs text-slate-400">{{ $product->sku }} · {{ $product->category->name }}</p></td><td class="px-5 py-4 font-semibold text-slate-700">{{ number_format($inventory?->on_hand_quantity ?? 0, 0, ',', '.') }} {{ $product->unit }}</td><td class="px-5 py-4 text-slate-500">{{ number_format($inventory?->reserved_quantity ?? 0, 0, ',', '.') }}</td><td class="px-5 py-4 font-semibold text-slate-700">{{ number_format(($inventory?->on_hand_quantity ?? 0) - ($inventory?->reserved_quantity ?? 0), 0, ',', '.') }}</td><td class="px-5 py-4 text-slate-500">{{ number_format($inventory?->incoming_quantity ?? 0, 0